 raciocínio e reparar erros comuns.","questionIds":["v5-portuguese-argument-evidence-25","v5-portuguese-argument-evidence-26","v5-portuguese-argument-evidence-27","v5-portuguese-argument-evidence-28","v5-portuguese-argument-evidence-29"]},{"stage":"REVIEW","focus":"Revisar evidência, estratégia e comunicação.","questionIds":["v5-portuguese-argument-evidence-30","v5-portuguese-argument-evidence-31","v5-portuguese-argument-evidence-32","v5-portuguese-argument-evidence-33","v5-portuguese-argument-evidence-34","v5-portuguese-argument-evidence-35","v5-portuguese-argument-evidence-36","v5-portuguese-argument-evidence-37","v5-portuguese-argument-evidence-38","v5-portuguese-argument-evidence-39","v5-portuguese-argument-evidence-40"]}],"micro_explanations":[{"trigger":"READ_CONTEXT","text":"Leia contexto, pergunta e condição antes de concluir."},{"trigger":"BOUND_CLAIM","text":"A resposta correta não afirma mais do que a situação sustenta."},{"trigger":"CHECK_EVIDENCE","text":"Identifique fonte, medida, regra ou observação usada."},{"trigger":"REPAIR_ERROR","text":"Quando errar, compare sua resposta com o aspecto que a pergunta realmente mede."}],"remediations":[{"id":"LOCATE_SCOPE","misconception":"Ignorar contexto, condição, fonte ou recorte.","prompt":"Sublinhe quem, quando, onde e em quais condições. Reescreva a resposta com esses limites."},{"id":"SEPARATE_OBSERVATION","misconception":"Confundir observação, interpretação, causa ou julgamento.","prompt":"Faça duas colunas: o que foi observado e o que seria uma interpretação adicional."},{"id":"CHECK_COMPARISON","misconception":"Comparar situações sem manter critérios equivalentes.","prompt":"Liste o que é igual, o que mudou e qual critério permite uma comparação justa."},{"id":"TRANSFER_CONTEXT","misconception":"Aplicar uma regra de um caso a todos os casos.","prompt":"Identifique o que permanece igual e o que mudou no novo contexto antes de transferir o raciocínio."}],"review_windows_days":[1,3,7],"review_schedule_statu